#!/bin/bash
# Date helpers. Dates are YYYY-MM-DD; month 01-12, day 01-31 (cli-conventions.md).
# check_date DATE: succeeds for a valid date; otherwise prints "bad date" to stderr and fails (callers exit 2).
check_date() {
  if ! [[ "$1" =~ ^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$ ]]; then
    echo "bad date: $1 (expected YYYY-MM-DD)" >&2
    return 1
  fi
}

