#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\n' > "$t"
for s in src/list.sh src/remind.sh; do
  for d in 2026/01/01 2026-13-01 2026-01-32 2026-00-10; do
    BOOKINGS=$t bash "$s" "$d" >/dev/null 2>&1; [ $? = 2 ] || { echo "$s $d should exit 2"; fail=1; }
    [ "$(BOOKINGS=$t bash "$s" "$d" 2>&1 >/dev/null)" = "bad date: $d (expected YYYY-MM-DD)" ] || { echo "$s $d: bad date message"; fail=1; }
    [ -z "$(BOOKINGS=$t bash "$s" "$d" 2>/dev/null)" ] || { echo "$s $d: stdout should be empty"; fail=1; }
  done
  BOOKINGS=$t bash "$s" 2026-01-02 >/dev/null 2>&1; [ $? = 0 ] || { echo "$s: a valid date should exit 0"; fail=1; }
done
[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-02)" = 'reminder to x: aoi 2026-01-02 10:00-11:00' ] || { echo "remind by date"; fail=1; }
rm -f "$t"; exit $fail

